argv:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
$edge=Get-Process msedge -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1
if($null -eq $edge){throw 'No visible Edge window'}
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$target=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('5LiL6LyJ5Y6f5bC65a+45ZyW54mH'))
$btn=$null
for($i=0;$i -lt $all.Count;$i++){
 $e=$all.Item($i)
 if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and [string]$e.Current.Name -eq $target){$btn=$e;break}
}
if($null -eq $btn){throw 'Gemini download button not found'}
try{
 $invoke=$btn.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern)
 $invoke.Invoke()
}catch{
 $btn.SetFocus()
 Add-Type -AssemblyName System.Windows.Forms
 [System.Windows.Forms.SendKeys]::SendWait('{ENTER}')
}
Start-Sleep -Seconds 8
$downloads=Join-Path $env:USERPROFILE 'Downloads'
$files=Get-ChildItem -LiteralPath $downloads -File -ErrorAction SilentlyContinue |
  Where-Object {$_.Extension -match '(?i)^\.(png|jpg|jpeg|webp)$'} |
  Sort-Object LastWriteTime -Descending |
  Select-Object -First 8 |
  ForEach-Object {[pscustomobject]@{name=$_.Name;path=$_.FullName;bytes=$_.Length;last_write=[string]$_.LastWriteTime}}
[pscustomobject]@{clicked=$true;downloads=$files}|ConvertTo-Json -Depth 5 -Compress
